import type {
  ApiServerDomainVerificationMethod,
  SchemaVaultsApiServerDomainRef,
} from "@schemavaults/app-definitions";

import type { Insertable, Selectable, Updateable } from "@schemavaults/dbh";

/**
 * Database representation of a domain registered for an API server: the
 * API-facing `SchemaVaultsApiServerDomainRef` plus its ownership
 * verification (migration 00057), which the ref schema does not carry (it
 * is `.strict()` and also the body of `POST /api/apis/{api_server_id}/domains`).
 *
 * - `verification_token` is generated by the auth server on insert; the
 *   domain's owner publishes it in DNS (`lib/api-server-domain-verification/`).
 * - `verified_at` (epoch ms; BIGINT, so it may come back as a string) and
 *   `verification_method` are both NULL while the registration is pending
 *   and both set once it is verified (a CHECK constraint keeps them in step).
 *   Verified rows take precedence in RFC 8707 resource-URL resolution;
 *   unverified ones are only a fallback while the
 *   `require_api_server_domain_verification` server setting is off.
 */
export type ApiServerDomainsTable = SchemaVaultsApiServerDomainRef & {
  verification_token: string;
  verified_at: number | string | null;
  verification_method: ApiServerDomainVerificationMethod | null;
};

export type ApiServerDomain = Selectable<ApiServerDomainsTable>;
export type NewApiServerDomain = Insertable<ApiServerDomainsTable>;
export type ApiServerDomainUpdate = Updateable<ApiServerDomainsTable>;

/** The columns of `SchemaVaultsApiServerDomainRef`, for explicit selects. */
export const API_SERVER_DOMAIN_REF_COLUMNS = [
  "api_server_domain_ref_id",
  "api_server_id",
  "domain",
  "environment",
  "created_at",
  "hardcoded",
] as const satisfies readonly (keyof SchemaVaultsApiServerDomainRef)[];
